{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In a constant infusion rat study, the closest analogue Compound 10 had a Kp,uu of 0.37 and was classified as BBB-permeable, directly demonstrating meaningful unbound brain exposure for this acryloyl-piperidine BTK inhibitor scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Oral tolebrutinib, fenebrutinib, and evobrutinib—close BTK inhibitors with the same chemotype—were detected in non-human primate CSF at pharmacologically relevant doses, confirming CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tirabrutinib, a close analogue, showed rapid brain absorption after oral dosing in rats with an unbound brain-to-plasma ratio of 8.5% at Cmax and was labeled BBB-permeable, supporting meaningful CNS exposure despite potential efflux considerations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Compound 9q, a structurally related piperidine-containing molecule, achieved a brain/plasma ratio of 2.7 after IV dosing, demonstrating that this scaffold can retain CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple highly transferable direct in vivo measurements in close BTK-inhibitor analogues demonstrate meaningful CNS access (Kp,uu 0.37, CSF detection, measurable unbound brain exposure, and brain/plasma ratios >1), and the query shares the same acryloyl-piperidine BTK-inhibitor scaffold.",
  "evidence_gaps": [
    "No direct Kp,uu or CSF measurement for the exact query molecule; prediction relies on highly transferable close analogues.",
    "Exact efflux transporter profile of the query is not explicitly measured, but multiple close analogues show measurable CNS exposure despite potential efflux."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

